import type { PullRequest, PullRequestCreate, PullRequestUpdate } from './model';
import { PullRequestRepository, PullRequestNotFoundError } from './repository';
import { validatePullRequestCreate, validatePullRequestUpdate } from './validator';

export interface PullRequestServiceDeps {
  repository: PullRequestRepository;
  clock?: () => Date;
  logger?: (msg: string, meta?: Record<string, unknown>) => void;
}

export interface ListPullRequestOptions {
  offset?: number;
  limit?: number;
  sortBy?: keyof PullRequest;
  order?: 'asc' | 'desc';
}

/**
 * Business-logic layer above PullRequestRepository.
 */
export class PullRequestService {
  private readonly repo: PullRequestRepository;
  private readonly clock: () => Date;
  private readonly logger: (msg: string, meta?: Record<string, unknown>) => void;

  constructor(deps: PullRequestServiceDeps) {
    this.repo = deps.repository;
    this.clock = deps.clock ?? (() => new Date());
    this.logger = deps.logger ?? (() => { /* noop */ });
  }

  create(input: PullRequestCreate): PullRequest {
    const errors = validatePullRequestCreate(input);
    if (errors.length > 0) throw new PullRequestValidationError(errors);
    const created = this.repo.insert(input);
    this.logger('PullRequestService.create', { id: created.id });
    return created;
  }

  get(id: string): PullRequest {
    return this.repo.requireById(id);
  }

  tryGet(id: string): PullRequest | undefined {
    return this.repo.findById(id);
  }

  update(id: string, patch: PullRequestUpdate): PullRequest {
    const errors = validatePullRequestUpdate(patch);
    if (errors.length > 0) throw new PullRequestValidationError(errors);
    const updated = this.repo.update(id, patch);
    this.logger('PullRequestService.update', { id });
    return updated;
  }

  delete(id: string): void {
    const existed = this.repo.delete(id);
    if (!existed) throw new PullRequestNotFoundError(id);
    this.logger('PullRequestService.delete', { id });
  }

  list(options: ListPullRequestOptions = {}): PullRequest[] {
    const offset = options.offset ?? 0;
    const limit = options.limit ?? 50;
    if (options.sortBy) {
      const sorted = this.repo.sortedBy(options.sortBy, options.order);
      return sorted.slice(offset, offset + limit);
    }
    return this.repo.paginate(offset, limit);
  }

  countAll(): number {
    return this.repo.count();
  }

  batchCreate(inputs: PullRequestCreate[]): PullRequest[] {
    for (const input of inputs) {
      const errors = validatePullRequestCreate(input);
      if (errors.length > 0) throw new PullRequestValidationError(errors);
    }
    return this.repo.batchInsert(inputs);
  }

  exists(id: string): boolean {
    return this.repo.findById(id) !== undefined;
  }

  bulkDelete(ids: string[]): number {
    let deleted = 0;
    for (const id of ids) if (this.repo.delete(id)) deleted++;
    return deleted;
  }

  searchByField<K extends keyof PullRequest>(field: K, value: PullRequest[K]): PullRequest[] {
    return this.repo.filter((entity) => entity[field] === value);
  }
}

export class PullRequestServiceError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'PullRequestServiceError';
  }
}

export class PullRequestValidationError extends Error {
  constructor(public readonly errors: string[]) {
    super(`PullRequest validation failed: ${errors.join('; ')}`);
    this.name = 'PullRequestValidationError';
  }
}
